import type { Role } from './role-model';
import type { Workspace } from './workspace-model';
import type { WorkspaceMembership } from './workspace-membership-model';

export interface MembershipRole {
  /**
   * @displayName Membership Role ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Membership Role Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  membershipRoleName: string;
  /**
   * @displayName Role Definition
   * @validationRule Required for create/update operations
   */
  roleDefinition: Pick<Role, 'id' | 'roleName'>;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
  /**
   * @displayName Workspace Membership
   * @validationRule Required for create/update operations
   */
  workspaceMembership: Pick<WorkspaceMembership, 'id' | 'membershipLabel'>;
}

export const _MembershipRole = 'MembershipRole' as const;